"""Explicit numerical selection and stream inputs for the reactive-source assay.

Original route and seed custody remains separate from current record custody.
Callers must verify supplied mappings before issue; these inputs do not transfer
historical qualification or permission to execute a source.
"""

from dataclasses import dataclass
from hashlib import sha256
from typing import ClassVar

from empirical_lawhood.kernel.serialization import CanonicalRecord, canonical_json_bytes, validate_sha256, validate_stable_id


@dataclass(frozen=True, slots=True)
class MatrixReactiveSourceHistoryScientificInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = "empirical-lawhood/scientific-input/matrix-reactive-source-history"

    history_index: int
    history_seed_sha256: str
    bridge_seed_sha256: str
    has_fine_view: bool
    development_checkpoint_steps: tuple[int, ...]
    control_start_index: int

    def __post_init__(self) -> None:
        if type(self.history_index) is not int or not 0 <= self.history_index < 256:
            raise ValueError("reactive-source scientific history index differs")
        if type(self.has_fine_view) is not bool:
            raise ValueError("reactive-source fine selection must be explicit")
        if type(self.control_start_index) is not int or not 0 <= self.control_start_index < 57:
            raise ValueError("reactive-source control order input differs")
        if self.development_checkpoint_steps and (
            len(self.development_checkpoint_steps) != 16
            or tuple(sorted(set(self.development_checkpoint_steps))) != self.development_checkpoint_steps
            or any(type(step) is not int or not 512 <= step <= 4096 or step % 64 for step in self.development_checkpoint_steps)
        ):
            raise ValueError("reactive-source checkpoint order input differs")
        for name in ("history_seed_sha256", "bridge_seed_sha256"):
            validate_sha256(getattr(self, name), field_name=name)


@dataclass(frozen=True, slots=True)
class MatrixReactiveSourceFutureScientificInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = "empirical-lawhood/scientific-input/matrix-reactive-source-future"

    arm_ordinal: int
    checkpoint_step: int
    future_index: int
    scientific_seed_sha256: str
    bridge_seed_sha256: str | None

    def __post_init__(self) -> None:
        if (
            type(self.arm_ordinal) is not int or self.arm_ordinal not in (0, 1, 2)
            or type(self.checkpoint_step) is not int or not 512 <= self.checkpoint_step <= 4096 or self.checkpoint_step % 64
            or type(self.future_index) is not int or not 0 <= self.future_index < 16
        ):
            raise ValueError("reactive-source future numerical coordinates differ")
        validate_sha256(self.scientific_seed_sha256, field_name="scientific_seed_sha256")
        if self.bridge_seed_sha256 is not None:
            validate_sha256(self.bridge_seed_sha256, field_name="bridge_seed_sha256")

    @property
    def coordinates(self) -> tuple[int, int, int]:
        return self.arm_ordinal, self.checkpoint_step, self.future_index


@dataclass(frozen=True, slots=True)
class MatrixReactiveSourceRoutingScientificInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = "empirical-lawhood/scientific-input/matrix-reactive-source-routing"

    history_index: int
    view_ordinal: int
    original_routing_sha256: str
    target_routing_sha256: str
    futures: tuple[MatrixReactiveSourceFutureScientificInput, ...]

    def __post_init__(self) -> None:
        if type(self.history_index) is not int or not 0 <= self.history_index < 256:
            raise ValueError("reactive-source routing history input differs")
        if type(self.view_ordinal) is not int or self.view_ordinal not in (0, 1):
            raise ValueError("reactive-source routing view input differs")
        for name in ("original_routing_sha256", "target_routing_sha256"):
            validate_sha256(getattr(self, name), field_name=name)
        if any(not isinstance(value, MatrixReactiveSourceFutureScientificInput) for value in self.futures):
            raise ValueError("reactive-source routing requires typed future inputs")
        coordinates = tuple(value.coordinates for value in self.futures)
        if tuple(sorted(set(coordinates))) != coordinates:
            raise ValueError("reactive-source routing future census must be complete and ordered")
        if any((value.bridge_seed_sha256 is not None) != bool(self.view_ordinal) for value in self.futures):
            raise ValueError("reactive-source bridge input differs from numerical view")

    def require_target_routing(
        self, *, target_routing_sha256: str, branch_coordinates: tuple[tuple[int, int, int], ...]
    ) -> None:
        if (
            self.target_routing_sha256 != target_routing_sha256
            or tuple(value.coordinates for value in self.futures) != branch_coordinates
        ):
            raise ValueError("reactive-source scientific input target routing custody differs")

    def future(self, coordinates: tuple[int, int, int]) -> MatrixReactiveSourceFutureScientificInput:
        for value in self.futures:
            if value.coordinates == coordinates:
                return value
        raise ValueError("reactive-source future lacks an issued scientific seed input")


@dataclass(frozen=True, slots=True)
class MatrixReactiveSourceAnalysisScientificInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = "empirical-lawhood/scientific-input/matrix-reactive-source-analysis"

    original_analysis_identity_sha256: str
    target_analysis_id: str
    development_threshold_seed_sha256: tuple[str, ...]
    evaluation_seed_sha256: str

    def __post_init__(self) -> None:
        validate_sha256(self.original_analysis_identity_sha256, field_name="original_analysis_identity_sha256")
        validate_stable_id(self.target_analysis_id, field_name="target_analysis_id")
        if len(self.development_threshold_seed_sha256) != 19:
            raise ValueError("reactive-source analysis requires all nineteen threshold seeds in numeric order")
        for value in self.development_threshold_seed_sha256:
            validate_sha256(value, field_name="development_threshold_seed_sha256")
        validate_sha256(self.evaluation_seed_sha256, field_name="evaluation_seed_sha256")

    def require_target_analysis(self, analysis_id: str) -> None:
        if analysis_id != self.target_analysis_id:
            raise ValueError("reactive-source analysis scientific input target custody differs")

    def threshold_seed(self, threshold: float) -> str:
        for index, percentage in enumerate(range(5, 100, 5)):
            if threshold == percentage / 100:
                return self.development_threshold_seed_sha256[index]
        raise ValueError("reactive-source analysis threshold lacks an issued scientific seed input")


def original_routing_scientific_input_sha256(inputs: tuple[MatrixReactiveSourceRoutingScientificInput, ...]) -> str:
    return sha256(canonical_json_bytes(tuple(
        (value.history_index, value.view_ordinal, value.original_routing_sha256,
         tuple((item.arm_ordinal, item.checkpoint_step, item.future_index,
                item.scientific_seed_sha256, item.bridge_seed_sha256) for item in value.futures))
        for value in inputs
    ))).hexdigest()


