def reactive_source_history_scientific_inputs(*, tranche_ordinal: int) -> tuple[MatrixReactiveSourceHistoryScientificInput, ...]:
    if type(tranche_ordinal) is not int or tranche_ordinal not in (0, 1):
        raise ValueError("reactive-source scientific input tranche role differs")
    return tuple(MatrixReactiveSourceHistoryScientificInput(*row) for row in _HISTORY_ROWS[tranche_ordinal])
